import * as React from "react";
import { cn } from "@/lib/utils";
import { announce } from "@/lib/announce";

export type DrawerActionTone = "danger" | "warning";

export interface DrawerActionProps {
  /** Icon shown above the label (mobile) or beside it (desktop). Phosphor or any node; sized to 20px. */
  icon: React.ReactNode;
  /** Text label rendered below the icon. */
  label: string;
  /** Click handler for plain actions (e.g. Cancel). */
  onClick?: () => void;
  /**
   * Button type. Use `"submit"` together with `form` so a Save action can
   * submit a `<form>` rendered in the drawer's scrollable content (the footer
   * sits outside that form in the DOM).
   */
  type?: "button" | "submit";
  /** Associates a `type="submit"` action with a form by its `id`. */
  form?: string;
  /** Disable the action (e.g. Save until the form is dirty/valid). */
  disabled?: boolean;
  /**
   * Turns this into a tap-again-to-confirm action. The first activation arms it
   * (icon + label swap to this confirm variant, tinted by `tone`); the second
   * runs `onConfirm`. Pair with `armed` / `onArmedChange` to keep sibling
   * destructive actions mutually exclusive and to reset on drawer close.
   */
  confirm?: {
    icon: React.ReactNode;
    label: string;
    /** @default "danger" */
    tone?: DrawerActionTone;
  };
  onConfirm?: () => void;
  /** Controlled armed state. When omitted the component manages its own. */
  armed?: boolean;
  onArmedChange?: (armed: boolean) => void;
  /** Accessible label when the visible label needs supplementing. */
  "aria-label"?: string;
  className?: string;
  /** Inline styles for the root element. */
  style?: React.CSSProperties;
}

/**
 * A single action in a `BottomDrawer` footer: an icon stacked above the label
 * on mobile (bottom-nav item style) and inline beside it on desktop, mirroring
 * how the app nav shifts from the mobile bottom bar to the desktop header.
 * Footers lay these out in an even flex row (most-destructive leftmost), e.g.
 * `Delete | Reset | Cancel | Save`.
 *
 * Two modes:
 * - **Plain** -- `onClick` (Cancel), or `type="submit"` + `form` (Save).
 * - **Confirm** -- pass `confirm` + `onConfirm` for tap-again-to-confirm.
 *   At rest the action is untinted; only the armed confirmation step tints
 *   (`tone="danger"` red, `tone="warning"` amber).
 *
 * @example
 * ```tsx
 * <DrawerAction icon={<X />} label={t('common.cancel')} onClick={onClose} />
 * <DrawerAction icon={<Check />} label={t('common.save')} type="submit" form="edit-goal" disabled={!dirty} />
 * <DrawerAction
 *   icon={<Trash />} label={t('settings.removeGoal')}
 *   confirm={{ icon: <Warning />, label: t('common.confirm'), tone: 'danger' }}
 *   onConfirm={handleRemove} armed={removeArmed} onArmedChange={setRemoveArmed}
 * />
 * ```
 */
export const DrawerAction = React.forwardRef<HTMLButtonElement, DrawerActionProps>(function DrawerAction({
  icon,
  label,
  onClick,
  type = "button",
  form,
  disabled,
  confirm,
  onConfirm,
  armed: controlledArmed,
  onArmedChange,
  className,
  style,
  ...rest
}, ref) {
  const [internalArmed, setInternalArmed] = React.useState(false);
  const isControlled = controlledArmed !== undefined;
  const armed = isControlled ? controlledArmed : internalArmed;

  const setArmed = React.useCallback(
    (next: boolean) => {
      if (!isControlled) setInternalArmed(next);
      onArmedChange?.(next);
    },
    [isControlled, onArmedChange]
  );

  const isConfirm = Boolean(confirm && onConfirm);

  const handleClick = () => {
    if (isConfirm) {
      if (armed) {
        onConfirm!();
        setArmed(false);
      } else {
        setArmed(true);
        // Announce the confirm label assertively so screen-reader users hear
        // "press again to confirm" before the destructive second activation.
        announce(confirm!.label, "assertive");
      }
      return;
    }
    onClick?.();
  };

  const showConfirm = isConfirm && armed;
  const tone = confirm?.tone ?? "danger";

  return (
    <button
      ref={ref}
      type={type}
      form={form}
      disabled={disabled}
      // A submit action lets the form handle activation; everything else
      // (plain + confirm) runs through handleClick.
      onClick={type === "submit" && !isConfirm ? onClick : handleClick}
      style={style}
      className={cn(
        // Stacked (icon over label) on mobile -- like a bottom-nav item -- and
        // inline (icon beside label) on desktop, mirroring how the app nav goes
        // from the mobile bottom bar to the desktop header.
        "flex flex-1 min-w-0 flex-col md:flex-row items-center justify-center gap-1 md:gap-2",
        "rounded-xl px-1.5 md:px-3 py-2.5 text-xs md:text-sm font-medium transition-colors",
        "[&_svg]:size-5 wj-focus-ring",
        disabled
          ? "opacity-40 pointer-events-none text-[var(--color-text-muted-light)] dark:text-[var(--color-text-muted-dark)]"
          : showConfirm
            ? tone === "warning"
              ? "text-[var(--color-warning-600)] dark:text-[var(--color-warning-400)]"
              : "text-[var(--color-error-600)] dark:text-[var(--color-error-400)]"
            : "text-[var(--color-text-secondary-light)] dark:text-[var(--color-text-secondary-dark)] hover:text-[var(--color-text-primary-light)] dark:hover:text-[var(--color-text-primary-dark)]",
        className
      )}
      {...rest}
    >
      <span aria-hidden className="flex items-center justify-center">
        {showConfirm ? confirm!.icon : icon}
      </span>
      <span className="leading-tight text-center">
        {showConfirm ? confirm!.label : label}
      </span>
    </button>
  );
});

DrawerAction.displayName = "DrawerAction"
